WITH c_rows AS (
    SELECT bond_type
    FROM c_cols
    WHERE bond_type IS NOT NULL
)
SELECT * FROM c_rows;

WITH t_bond_counts AS (
    SELECT bond_type, COUNT(*) AS count
    FROM c_rows
    GROUP BY bond_type
)
SELECT * FROM t_bond_counts;

WITH t_charcinogenic AS (
    SELECT m.label
    FROM molecule AS m
    WHERE m.molecule_id = 'TR010'
)
SELECT * FROM t_charcinogenic;

WITH final_answer AS (
    SELECT bond_type, count, CASE WHEN count = (SELECT MAX(count) FROM t_bond_counts) THEN 'Yes' ELSE 'No' END AS is_majority
    FROM t_bond_counts
)
SELECT * FROM final_answer;

WITH t_final AS (
    SELECT f.bond_type, f.count, f.is_majority, c.label
    FROM final_answer f
    JOIN t_charcinogenic c ON 1=1
)
SELECT * FROM t_final;

WITH final_result AS (
    SELECT bond_type, count, is_majority, label
    FROM t_final
    WHERE label = '-'
)
SELECT * FROM final_result;

